#!/usr/bin/env python3
"""Generate product labels from release/version.json. --check fails on drift."""
import json,sys
from pathlib import Path
root=Path(__file__).resolve().parents[1]
v=json.loads((root/'release/version.json').read_text())
outputs={
 'apps/loom/lib/app/release_metadata.dart':"// Generated by scripts/sync-release-metadata.py; do not edit.\nconst loomReleaseChannel = '%s';\nconst loomReleaseVersion = '%s';\n"%(v['channel'],v['version']),
 'services/loom_server/src/release_metadata.ts':"// Generated by scripts/sync-release-metadata.py; do not edit.\nexport const releaseChannel = '%s';\nexport const releaseVersion = '%s';\n"%(v['channel'],v['version'])}
for name,content in outputs.items():
 p=root/name
 if '--check' in sys.argv:
  if not p.exists() or p.read_text()!=content:sys.exit('Release metadata drift: '+name)
 else:p.write_text(content)
